@tailwind base;
@tailwind components;
@tailwind utilities;

/* Design tokens — BookMyShow red/white/black. Light theme. */
:root {
  --color-background: 250 249 248; /* neutral-50 */
  --color-surface: 255 255 255;
  --color-surface-raised: 244 243 242; /* neutral-100 */
  --color-foreground: 26 25 23; /* neutral-900 */
  --color-foreground-muted: 125 120 117; /* neutral-500 */
  --color-border: 230 228 227; /* neutral-200 */
  --color-ring: 226 56 47; /* primary-500 */
  --font-display: "Poppins", system-ui, sans-serif;
  --font-sans: "Inter", system-ui, sans-serif;
}

@layer base {
  html {
    @apply scroll-smooth;
  }
  body {
    @apply bg-background text-foreground font-sans antialiased;
  }
  h1,
  h2,
  h3,
  h4 {
    @apply font-display font-bold tracking-tight text-foreground;
  }
  a {
    @apply text-primary-600 hover:text-primary-700 transition-colors;
  }
  input,
  select,
  textarea {
    @apply block w-full rounded-lg border border-border bg-surface px-4 py-2.5 text-foreground placeholder:text-foreground-muted focus:outline-none focus:ring-2 focus:ring-ring/40 focus:border-ring;
  }
  ::selection {
    @apply bg-primary-500 text-white;
  }
}

@layer components {
  .container-page {
    @apply mx-auto w-full max-w-6xl px-4 sm:px-6 lg:px-8;
  }
}

/* Honor reduced motion: collapse non-essential transitions. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

import type { Metadata } from "next";
import { Header } from "@/components/Header";
import "./globals.css";

export const metadata: Metadata = {
  title: "BookMyShow Replica — Book Movie Tickets",
  description:
    "Browse currently showing movies, pick a theatre and seats, and book your tickets online.",
};

/**
 * Root layout for the BookMyShow Replica frontend.
 *
 * Loads the brand fonts, applies the global token stylesheet, and wraps every
 * page in the shared sticky header.
 */
export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en">
      <body>
        <Header />
        <main>{children}</main>
      </body>
    </html>
  );
}

import { ButtonHTMLAttributes, forwardRef } from "react";

type ButtonVariant = "primary" | "secondary" | "ghost";
type ButtonSize = "sm" | "md" | "lg";

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** Visual variant. */
  variant?: ButtonVariant;
  /** Size scale. */
  size?: ButtonSize;
  /** Show a loading spinner and disable interaction. */
  loading?: boolean;
}

const variants: Record<ButtonVariant, string> = {
  primary:
    "bg-primary-500 text-white shadow-card hover:bg-primary-600 hover:shadow-card-hover hover:-translate-y-0.5 focus-visible:shadow-glow",
  secondary:
    "bg-surface-raised/80 border border-border text-foreground hover:bg-surface-raised",
  ghost: "text-foreground hover:bg-surface-raised",
};

const sizes: Record<ButtonSize, string> = {
  sm: "px-3 py-1.5 text-sm",
  md: "px-5 py-2.5 text-sm",
  lg: "px-6 py-3 text-base",
};

/**
 * Button primitive.
 *
 * Variants and sizes are expressed as lookup maps so styling stays consistent
 * and additions are centralized. Forwards a ref and all native button props.
 */
export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  function Button(
    {
      variant = "primary",
      size = "md",
      loading = false,
      disabled,
      className = "",
      children,
      ...props
    },
    ref
  ) {
    return (
      <button
        ref={ref}
        disabled={disabled || loading}
        className={`inline-flex items-center justify-center gap-2 rounded-full font-semibold transition-all duration-200 ease-out focus:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-60 ${variants[variant]} ${sizes[size]} ${className}`}
        {...props}
      >
        {loading && (
          <svg
            className="h-4 w-4 animate-spin"
            viewBox="0 0 24 24"
            fill="none"
            aria-hidden="true"
          >
            <circle
              className="opacity-25"
              cx="12"
              cy="12"
              r="10"
              stroke="currentColor"
              strokeWidth="4"
            />
            <path
              className="opacity-90"
              fill="currentColor"
              d="M4 12a8 8 0 018-8v4a4 4 0 00-4 4H4z"
            />
          </svg>
        )}
        {children}
      </button>
    );
  }
);

