/**
 * Shared domain types and DTOs for the BookMyShow Replica backend.
 */

/** A movie in the catalog. */
export interface Movie {
  id: number;
  title: string;
  poster: string;
  genre: string;
  rating: string;
}

/** A theatre showing movies. */
export interface Theatre {
  id: number;
  name: string;
  location: string;
}

/** A persisted booking. */
export interface Booking {
  id: number;
  confirmationId: string;
  mobile: string;
  movieId: number;
  theatreId: number;
  seats: string[];
  totalPrice: number;
  paymentMethod: PaymentMethod;
  createdAt: string;
}

/** Supported dummy payment methods. */
export type PaymentMethod = "card" | "upi";

/** Standard success envelope. */
export interface SuccessResponse<T> {
  success: true;
  data?: T;
  message?: string;
  token?: string;
}

/** Standard error envelope. */
export interface ErrorResponse {
  success: false;
  error: string;
}

import { Request, Response, NextFunction } from "express";
import { ZodSchema, ZodError } from "zod";

/**
 * Request-body validation middleware factory.
 *
 * Validates `req.body` against a zod schema at the trust boundary. On success
 * the parsed (typed) body replaces `req.body`; on failure it responds `400`
 * with the first validation message and does not call the handler.
 *
 * Args:
 *   schema: The zod schema to validate the request body against.
 *
 * Returns:
 *   An Express middleware function.
 */
export function validateBody(schema: ZodSchema) {
  return (req: Request, res: Response, next: NextFunction): void => {
    try {
      req.body = schema.parse(req.body);
      next();
    } catch (err) {
      if (err instanceof ZodError) {
        const message = err.errors
          .map((e) => `${e.path.join(".")}: ${e.message}`)
          .join("; ");
        res.status(400).json({ success: false, error: message });
        return;
      }
      next(err);
    }
  };
}

import jwt from "jsonwebtoken";
import { config } from "../config";

/** The hardcoded OTP accepted by this replica (no real SMS provider). */
export const HARDCODED_OTP = "1234";

/**
 * Authentication service.
 *
 * Implements the mobile-number + hardcoded-OTP login flow. No user record is
 * persisted; a successful OTP verification issues a signed session token.
 */
export class AuthService {
  /**
   * Begin a login by validating the mobile number.
   *
   * Args:
   *   mobile: The user's mobile number.
   *
   * Returns:
   *   True when the mobile number is a valid 10-digit identifier.
   */
  initiateLogin(mobile: string): boolean {
    return /^[0-9]{10}$/.test(mobile);
  }

  /**
   * Verify the OTP and, on success, issue a session token.
   *
   * Args:
   *   mobile: The user's mobile number.
   *   otp: The one-time password entered by the user.
   *
   * Returns:
   *   A signed JWT session token when the OTP matches.
   *
   * Raises:
   *   Error: With `status: 401` when the OTP does not match.
   */
  verifyOtp(mobile: string, otp: string): string {
    if (!this.initiateLogin(mobile)) {
      const err = new Error("Invalid mobile number") as Error & {
        status?: number;
      };
      err.status = 400;
      throw err;
    }
    if (otp !== HARDCODED_OTP) {
      const err = new Error("Invalid OTP") as Error & { status?: number };
      err.status = 401;
      throw err;
    }
    return jwt.sign({ mobile }, config.jwtSecret, { expiresIn: "2h" });
  }
}

export const authService = new AuthService();

import { Router, Request, Response, NextFunction } from "express";
import { z } from "zod";
import { authService } from "../services/auth.service";
import { validateBody } from "../middleware/validate";

const loginSchema = z.object({
  mobile: z
    .string()
    .regex(/^[0-9]{10}$/, "Mobile number must be 10 digits"),
});

const verifySchema = z.object({
  mobile: z
    .string()
    .regex(/^[0-9]{10}$/, "Mobile number must be 10 digits"),
  otp: z.string().min(1, "OTP is required"),
});

/**
 * Authentication router: mobile login and OTP verification.
 */
export const authRouter = Router();

/**
 * POST /api/auth/login — accept a mobile number to begin login.
 */
authRouter.post(
  "/login",
  validateBody(loginSchema),
  (req: Request, res: Response, next: NextFunction): void => {
    try {
      const { mobile } = req.body as z.infer<typeof loginSchema>;
      authService.initiateLogin(mobile);
      res
        .status(200)
        .json({ success: true, message: "OTP sent to your mobile number" });
    } catch (err) {
      next(err);
    }
  }
);

/**
 * POST /api/auth/verify — verify the OTP and issue a session token.
 */
authRouter.post(
  "/verify",
  validateBody(verifySchema),
  (req: Request, res: Response, next: NextFunction): void => {
    try {
      const { mobile, otp } = req.body as z.infer<typeof verifySchema>;
      const token = authService.verifyOtp(mobile, otp);
      res.status(200).json({ success: true, token });
    } catch (err) {
      next(err);
    }
  }
);

