import { describe, it, expect, vi, beforeEach } from "vitest";
import LoginPage from "@/app/login/page";
import { BookingProvider } from "@/context/BookingContext";

// Mock next/navigation's useRouter.
const pushMock = vi.fn();
vi.mock("next/navigation", () => ({
  useRouter: () => ({ push: pushMock, replace: vi.fn() }),
}));

// Mock the API client.
vi.mock("@/lib/api", async (importOriginal) => {
  const actual = await importOriginal<typeof import("@/lib/api")>();
  return {
    ...actual,
    login: vi.fn(),
  };
});

import { login } from "@/lib/api";

function renderLogin() {
  return render(
    <BookingProvider>
      <LoginPage />
    </BookingProvider>
  );
}

describe("LoginPage", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("renders the mobile number field and submit button", () => {
    renderLogin();
    expect(
      screen.getByLabelText(/mobile number/i)
    ).toBeInTheDocument();
    expect(
      screen.getByRole("button", { name: /continue/i })
    ).toBeInTheDocument();
  });

  it("shows a validation error for an invalid mobile number", async () => {
    renderLogin();
    await userEvent.type(screen.getByLabelText(/mobile number/i), "123");
    await userEvent.click(screen.getByRole("button", { name: /continue/i }));
    expect(
      await screen.findByText(/valid 10-digit mobile number/i)
    ).toBeInTheDocument();
    expect(login).not.toHaveBeenCalled();
  });

  it("submits a valid mobile number and navigates to the OTP screen", async () => {
    vi.mocked(login).mockResolvedValue({ success: true, message: "OTP sent" });
    renderLogin();
    await userEvent.type(
      screen.getByLabelText(/mobile number/i),
      "9876543210"
    );
    await userEvent.click(screen.getByRole("button", { name: /continue/i }));
    await waitFor(() => expect(login).toHaveBeenCalledWith("9876543210"));
    await waitFor(() => expect(pushMock).toHaveBeenCalledWith("/login/otp"));
  });

  it("shows an API error message when login fails", async () => {
    const { ApiError } = await import("@/lib/api");
    vi.mocked(login).mockRejectedValue(new ApiError("Server error", 500));
    renderLogin();
    await userEvent.type(
      screen.getByLabelText(/mobile number/i),
      "9876543210"
    );
    await userEvent.click(screen.getByRole("button", { name: /continue/i }));
    expect(await screen.findByText(/server error/i)).toBeInTheDocument();
  });
});

import { test, expect } from "@playwright/test";

/**
 * E2E for the authentication journey: mobile entry → OTP verification →
 * landing on the movie dashboard with a session established.
 */
test.describe("Authentication", () => {
  test("logs in with a mobile number and the hardcoded OTP", async ({
    page,
  }) => {
    const consoleErrors: string[] = [];
    page.on("pageerror", (err) => consoleErrors.push(err.message));

    await page.goto("/login");
    await expect(
      page.getByRole("heading", { name: /sign in/i })
    ).toBeVisible();

    // Enter a mobile number and continue to the OTP screen.
    await page.getByLabel(/mobile number/i).fill("9876543210");
    await page.getByRole("button", { name: /continue/i }).click();

    await expect(page).toHaveURL(/\/login\/otp/);
    await expect(
      page.getByRole("heading", { name: /enter otp/i })
    ).toBeVisible();

    // Enter the hardcoded OTP and verify.
    await page.getByLabel(/one-time password/i).fill("1234");
    await page.getByRole("button", { name: /verify/i }).click();

    // Lands on the movie dashboard.
    await expect(page).toHaveURL(/\/movies/);

    expect(consoleErrors).toEqual([]);
  });

  test("rejects an incorrect OTP with an error message", async ({ page }) => {
    await page.goto("/login");
    await page.getByLabel(/mobile number/i).fill("9876543210");
    await page.getByRole("button", { name: /continue/i }).click();
    await expect(page).toHaveURL(/\/login\/otp/);

    await page.getByLabel(/one-time password/i).fill("0000");
    await page.getByRole("button", { name: /verify/i }).click();

    await expect(page.getByText(/invalid otp/i)).toBeVisible();
  });
});

import Database from "better-sqlite3";
import fs from "fs";
import path from "path";
import { config } from "../config";

/**
 * SQLite database singleton.
 *
 * Opens a single file-backed connection shared across the app, ensures the
 * parent directory exists, and initializes the schema. Never open a
 * connection per request.
 */

let db: Database.Database | null = null;

/**
 * Get (creating on first use) the shared SQLite connection.
 *
 * Returns:
 *   The shared better-sqlite3 database instance.
 */
export function getDb(): Database.Database {
  if (db) {
    return db;
  }
  const dir = path.dirname(config.databasePath);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  db = new Database(config.databasePath);
  db.pragma("journal_mode = WAL");
  db.pragma("foreign_keys = ON");
  initSchema(db);
  return db;
}

/**
 * Initialize the database schema idempotently.
 *
 * Args:
 *   database: The database instance to initialize.
 */
function initSchema(database: Database.Database): void {
  database.exec(`
    CREATE TABLE IF NOT EXISTS movies (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      title TEXT NOT NULL,
      poster TEXT NOT NULL DEFAULT '',
      genre TEXT NOT NULL DEFAULT '',
      rating TEXT NOT NULL DEFAULT ''
    );
    CREATE TABLE IF NOT EXISTS theatres (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      location TEXT NOT NULL DEFAULT ''
    );
    CREATE TABLE IF NOT EXISTS movie_theatres (
      movie_id INTEGER NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
      theatre_id INTEGER NOT NULL REFERENCES theatres(id) ON DELETE CASCADE,
      PRIMARY KEY (movie_id, theatre_id)
    );
    CREATE TABLE IF NOT EXISTS bookings (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      confirmation_id TEXT NOT NULL UNIQUE,
      mobile TEXT NOT NULL,
      movie_id INTEGER NOT NULL REFERENCES movies(id),
      theatre_id INTEGER NOT NULL REFERENCES theatres(id),
      seats TEXT NOT NULL,
      total_price INTEGER NOT NULL,
      payment_method TEXT NOT NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
  `);
}

/**
 * Close the shared connection. Used by tests to reset state.
 */
export function closeDb(): void {
  if (db) {
    db.close();
    db = null;
  }
}

import { getDb } from "./database";

/**
 * Seed data for the replica catalog.
 *
 * The acceptance dataset from the PRD: three movies and three theatres, with
 * every theatre showing every movie.
 */
const MOVIES = [
  { title: "Paradise", poster: "/posters/paradise.svg", genre: "Drama", rating: "U/A" },
  { title: "Bloody Romeo", poster: "/posters/bloody-romeo.svg", genre: "Action", rating: "A" },
  { title: "OG2", poster: "/posters/og2.svg", genre: "Thriller", rating: "U/A" },
];

const THEATRES = [
  { name: "Sandhya 70mm", location: "Hyderabad" },
  { name: "Sudharsham 70mm", location: "Hyderabad" },
  { name: "Allu Cinemas", location: "Hyderabad" },
];

/**
 * Seed the database idempotently.
 *
 * Each insert is conditional on absence (checked by unique title/name), so
 * running seed on every startup never duplicates rows. Also maps every movie
 * to every theatre.
 */
export function seedDatabase(): void {
  const db = getDb();

  const insertMovie = db.prepare(
    "INSERT INTO movies (title, poster, genre, rating) SELECT ?, ?, ?, ? WHERE NOT EXISTS (SELECT 1 FROM movies WHERE title = ?)"
  );
  const insertTheatre = db.prepare(
    "INSERT INTO theatres (name, location) SELECT ?, ? WHERE NOT EXISTS (SELECT 1 FROM theatres WHERE name = ?)"
  );
  const insertMapping = db.prepare(
    "INSERT OR IGNORE INTO movie_theatres (movie_id, theatre_id) VALUES (?, ?)"
  );

  const seedAll = db.transaction(() => {
    for (const movie of MOVIES) {
      insertMovie.run(movie.title, movie.poster, movie.genre, movie.rating, movie.title);
    }
    for (const theatre of THEATRES) {
      insertTheatre.run(theatre.name, theatre.location, theatre.name);
    }
    const movieIds = db.prepare("SELECT id FROM movies").all() as { id: number }[];
    const theatreIds = db.prepare("SELECT id FROM theatres").all() as { id: number }[];
    for (const movie of movieIds) {
      for (const theatre of theatreIds) {
        insertMapping.run(movie.id, theatre.id);
      }
    }
  });

  seedAll();
}

import { getDb } from "../db/database";
import type { Movie, Theatre } from "../types";

/**
 * Movies catalog service — queries against the seeded database.
 */
export class MoviesService {
  /**
   * List every movie in the catalog.
   *
   * Returns:
   *   All movies, ordered by id.
   */
  listMovies(): Movie[] {
    const rows = getDb()
      .prepare("SELECT id, title, poster, genre, rating FROM movies ORDER BY id")
      .all();
    return rows as Movie[];
  }

  /**
   * Find a single movie by id.
   *
   * Args:
   *   id: The movie id.
   *
   * Returns:
   *   The movie, or undefined when it does not exist.
   */
  getMovie(id: number): Movie | undefined {
    const row = getDb()
      .prepare("SELECT id, title, poster, genre, rating FROM movies WHERE id = ?")
      .get(id);
    return row as Movie | undefined;
  }

  /**
   * List the theatres showing a given movie.
   *
   * Args:
   *   movieId: The movie id.
   *
   * Returns:
   *   The theatres mapped to that movie.
   */
  listTheatresForMovie(movieId: number): Theatre[] {
    const rows = getDb()
      .prepare(
        `SELECT t.id, t.name, t.location
         FROM theatres t
         JOIN movie_theatres mt ON mt.theatre_id = t.id
         WHERE mt.movie_id = ?
         ORDER BY t.id`
      )
      .all(movieId);
    return rows as Theatre[];
  }
}

export const moviesService = new MoviesService();

import { getDb } from "../db/database";
import type { Theatre } from "../types";

/**
 * Theatres service — queries against the seeded database.
 */
export class TheatresService {
  /**
   * List every theatre.
   *
   * Returns:
   *   All theatres, ordered by id.
   */
  listTheatres(): Theatre[] {
    const rows = getDb()
      .prepare("SELECT id, name, location FROM theatres ORDER BY id")
      .all();
    return rows as Theatre[];
  }

  /**
   * Find a single theatre by id.
   *
   * Args:
   *   id: The theatre id.
   *
   * Returns:
   *   The theatre, or undefined when it does not exist.
   */
  getTheatre(id: number): Theatre | undefined {
    const row = getDb()
      .prepare("SELECT id, name, location FROM theatres WHERE id = ?")
      .get(id);
    return row as Theatre | undefined;
  }
}

export const theatresService = new TheatresService();

import { Router, Request, Response, NextFunction } from "express";
import { moviesService } from "../services/movies.service";

/**
 * Movies router: catalog listing and per-movie theatre lookup.
 */
export const moviesRouter = Router();

/**
 * GET /api/movies — return the full movie catalog.
 */
moviesRouter.get(
  "/",
  (_req: Request, res: Response, next: NextFunction): void => {
    try {
      const movies = moviesService.listMovies();
      res.status(200).json({ movies });
    } catch (err) {
      next(err);
    }
  }
);

/**
 * GET /api/movies/:id/theatres — return the theatres showing a movie.
 */
moviesRouter.get(
  "/:id/theatres",
  (req: Request, res: Response, next: NextFunction): void => {
    try {
      const id = parseInt(req.params.id, 10);
      if (Number.isNaN(id)) {
        res.status(400).json({ success: false, error: "Invalid movie id" });
        return;
      }
      const movie = moviesService.getMovie(id);
      if (!movie) {
        res.status(404).json({ success: false, error: "Movie not found" });
        return;
      }
      const theatres = moviesService.listTheatresForMovie(id);
      res.status(200).json({ theatres });
    } catch (err) {
      next(err);
    }
  }
);

import { Router, Request, Response, NextFunction } from "express";
import { theatresService } from "../services/theatres.service";

/**
 * Theatres router: theatre listing.
 */
export const theatresRouter = Router();

/**
 * GET /api/theatres — return all theatres.
 */
theatresRouter.get(
  "/",
  (_req: Request, res: Response, next: NextFunction): void => {
    try {
      const theatres = theatresService.listTheatres();
      res.status(200).json({ theatres });
    } catch (err) {
      next(err);
    }
  }
);

