import { test, expect } from "@playwright/test";

/**
 * E2E for the full booking journey: log in → browse movies → pick a theatre →
 * select seats → pay → see the confirmation. Asserts on content served from
 * the backend, not just page loads.
 */
test.describe("Booking journey", () => {
  test("completes browse-to-booked end to end", async ({ page }) => {
    const consoleErrors: string[] = [];
    page.on("pageerror", (err) => consoleErrors.push(err.message));

    // Log in.
    await page.goto("/login");
    await page.getByLabel(/mobile number/i).fill("9876543210");
    await page.getByRole("button", { name: /continue/i }).click();
    await page.getByLabel(/one-time password/i).fill("1234");
    await page.getByRole("button", { name: /verify/i }).click();
    await expect(page).toHaveURL(/\/movies/);

    // The dashboard lists the seeded movies from the backend.
    await expect(
      page.getByRole("heading", { name: "Paradise" })
    ).toBeVisible();
    await expect(
      page.getByRole("heading", { name: "Bloody Romeo" })
    ).toBeVisible();
    await expect(page.getByRole("heading", { name: "OG2" })).toBeVisible();

    // Open a movie to see its theatres.
    await page.getByRole("heading", { name: "Paradise" }).click();
    await expect(page).toHaveURL(/\/movies\/\d+/);
    await expect(page.getByText("Sandhya 70mm")).toBeVisible();
    await expect(page.getByText("Sudharsham 70mm")).toBeVisible();
    await expect(page.getByText("Allu Cinemas")).toBeVisible();

    // Select a theatre and continue to seats.
    await page.getByText("Sandhya 70mm").click();
    await page
      .getByRole("button", { name: /continue to seats/i })
      .click();
    await expect(page).toHaveURL(/\/seats/);

    // Select the hardcoded seats and continue to payment.
    await page.getByRole("button", { name: /select seats/i }).click();
    await expect(page.getByText(/A1/)).toBeVisible();
    await expect(page.getByText(/450/)).toBeVisible();
    await page
      .getByRole("button", { name: /proceed to pay|continue|pay/i })
      .first()
      .click();
    await expect(page).toHaveURL(/\/payment/);

    // Pay with UPI.
    await page.getByLabel(/upi id/i).fill("user@upi");
    await page.getByRole("button", { name: /^pay/i }).click();

    // Processing state appears, then the success screen.
    await expect(page.getByText(/processing payment/i)).toBeVisible();
    await expect(
      page.getByText(/congratulations/i)
    ).toBeVisible({ timeout: 10000 });

    // Confirmation shows the booked movie, theatre, and seats.
    await expect(page.getByText("Paradise")).toBeVisible();
    await expect(page.getByText("Sandhya 70mm")).toBeVisible();
    await expect(page.getByText(/A1/)).toBeVisible();

    expect(consoleErrors).toEqual([]);
  });
});

import { randomBytes } from "crypto";
import { getDb } from "../db/database";
import { moviesService } from "./movies.service";
import { theatresService } from "./theatres.service";
import type { Booking, PaymentMethod } from "../types";

/** Payload accepted to create a booking. */
export interface CreateBookingInput {
  mobile: string;
  movieId: number;
  theatreId: number;
  seats: string[];
  totalPrice: number;
  paymentMethod: PaymentMethod;
}

/** The confirmation shape returned to the caller. */
export interface BookingConfirmation {
  id: number;
  confirmationId: string;
  movie: string;
  theatre: string;
  seats: string[];
  totalPrice: number;
}

/**
 * Bookings service — persists bookings and returns confirmations.
 */
export class BookingsService {
  /**
   * Create and persist a booking.
   *
   * Args:
   *   input: The booking details.
   *
   * Returns:
   *   The booking confirmation with a generated confirmation id.
   *
   * Raises:
   *   Error: With `status: 404` when the movie or theatre does not exist.
   */
  createBooking(input: CreateBookingInput): BookingConfirmation {
    const movie = moviesService.getMovie(input.movieId);
    if (!movie) {
      const err = new Error("Movie not found") as Error & { status?: number };
      err.status = 404;
      throw err;
    }
    const theatre = theatresService.getTheatre(input.theatreId);
    if (!theatre) {
      const err = new Error("Theatre not found") as Error & { status?: number };
      err.status = 404;
      throw err;
    }

    const confirmationId = `BMS-${randomBytes(4).toString("hex").toUpperCase()}`;
    const db = getDb();
    const result = db
      .prepare(
        `INSERT INTO bookings
         (confirmation_id, mobile, movie_id, theatre_id, seats, total_price, payment_method)
         VALUES (?, ?, ?, ?, ?, ?, ?)`
      )
      .run(
        confirmationId,
        input.mobile,
        input.movieId,
        input.theatreId,
        JSON.stringify(input.seats),
        input.totalPrice,
        input.paymentMethod
      );

    return {
      id: Number(result.lastInsertRowid),
      confirmationId,
      movie: movie.title,
      theatre: theatre.name,
      seats: input.seats,
      totalPrice: input.totalPrice,
    };
  }

  /**
   * Fetch a persisted booking by id.
   *
   * Args:
   *   id: The booking id.
   *
   * Returns:
   *   The booking, or undefined when it does not exist.
   */
  getBooking(id: number): Booking | undefined {
    const row = getDb()
      .prepare("SELECT * FROM bookings WHERE id = ?")
      .get(id) as
      | {
          id: number;
          confirmation_id: string;
          mobile: string;
          movie_id: number;
          theatre_id: number;
          seats: string;
          total_price: number;
          payment_method: PaymentMethod;
          created_at: string;
        }
      | undefined;
    if (!row) return undefined;
    return {
      id: row.id,
      confirmationId: row.confirmation_id,
      mobile: row.mobile,
      movieId: row.movie_id,
      theatreId: row.theatre_id,
      seats: JSON.parse(row.seats) as string[],
      totalPrice: row.total_price,
      paymentMethod: row.payment_method,
      createdAt: row.created_at,
    };
  }
}

export const bookingsService = new BookingsService();

import { Router, Request, Response, NextFunction } from "express";
import { z } from "zod";
import { bookingsService } from "../services/bookings.service";
import { validateBody } from "../middleware/validate";

const bookingSchema = z.object({
  mobile: z.string().regex(/^[0-9]{10}$/, "Mobile number must be 10 digits"),
  movieId: z.number().int().positive("movieId must be a positive integer"),
  theatreId: z.number().int().positive("theatreId must be a positive integer"),
  seats: z.array(z.string()).min(1, "At least one seat is required"),
  totalPrice: z.number().int().nonnegative("totalPrice must be non-negative"),
  paymentMethod: z.enum(["card", "upi"]),
});

/**
 * Bookings router: create a booking.
 */
export const bookingsRouter = Router();

/**
 * POST /api/bookings — persist a booking and return its confirmation.
 */
bookingsRouter.post(
  "/",
  validateBody(bookingSchema),
  (req: Request, res: Response, next: NextFunction): void => {
    try {
      const input = req.body as z.infer<typeof bookingSchema>;
      const booking = bookingsService.createBooking(input);
      res.status(201).json({ success: true, booking });
    } catch (err) {
      next(err);
    }
  }
);

