    vi.restoreAllMocks();
  });

  function mockFetch(status: number, body: unknown) {
    return vi.spyOn(global, "fetch").mockResolvedValue(
      new Response(JSON.stringify(body), {
        status,
        headers: { "Content-Type": "application/json" },
      })
    );
