    await expect(api.verifyOtp("9876543210", "0000")).rejects.toMatchObject({
      name: "ApiError",
      message: "Invalid OTP",
      status: 401,
    });
  });

  it("createBooking sends the Authorization header with the token", async () => {
    const spy = mockFetch(201, {
      success: true,
